 <body>
     <a href="#main" class="skip-link">Skip to main content</a>
     <div id="root"></div>

     <script>
         const { createElement: h, useState } = React;

         const FormField = ({ label, id, type, required, autocomplete, helperText, value, onChange }) => {
             return h('div', { className: 'form-field' },
                 h('label', { htmlFor: id },
                     label,
                     required && h('span', { className: 'required-indicator', 'aria-hidden': 'true' }, '*')
                 ),
                 h('input', {
                     id,
                     name: id,
                     type,
                     required,
                     autocomplete,
                     value,
                     onChange: (e) => onChange(e.target.value),
                     'aria-describedby': helperText ? `${id}-helper` : undefined
                 }),
                 helperText && h('p', { id: `${id}-helper`, className: 'helper-text' }, helperText)
             );
         };

         const App = () => {
             const [formData, setFormData] = useState({
                 name: '',
                 email: '',
                 phone: ''
             });

             const handleChange = (field) => (value) => {
                 setFormData(prev => ({ ...prev, [field]: value }));
             };

             const handleSubmit = (e) => {
                 e.preventDefault();
                 alert('Support request submitted!');
             };

             return h('main', { id: 'main', tabIndex: '-1' },
                 h('h1', null, 'Contact Support'),
                 h('p', { className: 'required-note' }, '* indicates required fields'),
                 h('form', { onSubmit: handleSubmit },
                     h(FormField, {
                         label: 'Full Name',
                         id: 'name',
                         type: 'text',
                         required: true,
                         autocomplete: 'name',
                         value: formData.name,
                         onChange: handleChange('name')
                     }),
                     h(FormField, {
                         label: 'Email Address',
                         id: 'email',
                         type: 'email',
                         required: true,
                         autocomplete: 'email',
                         value: formData.email,
                         onChange: handleChange('email')
                     }),
                     h(FormField, {
                         label: 'Phone Number',
                         id: 'phone',
                         type: 'tel',
                         required: false,
                         autocomplete: 'tel',
                         helperText: 'Expected format: 123-456-7890',
                         value: formData.phone,
                         onChange: handleChange('phone')
                     }),
                     h('button', { type: 'submit' }, 'Submit Request')
                 )
             );
         };

         const root = ReactDOM.createRoot(document.getElementById('root'));
         root.render(h(App));
     </script>
 </body>
 </html>

